def rec_extra():
    """Párrafos de la v3 en TradingView y del EA en MetaTrader 5 para la tarjeta de reconciliación."""
    out = ""
    if REC_V3:
        out += (f"<p><b>v3 · TradingView</b> (BINANCE:BTCUSDT, {fecha(REC_V3['desde'])} → {fecha(REC_V3['hasta'])}): {REC_V3['emparejadas']} de {REC_V3['motor']['n']} operaciones, "
                f"mismo precio de entrada (diferencia mediana {num(REC_V3['dif_precio_entrada_pct']['mediana'],3)} %), PF {num(REC_V3['tv']['pf'])} frente a {num(REC_V3['motor']['pf'])}.</p>")
    if REC_MT5:
        out += (f"<p><b>v3 · MetaTrader 5</b> (Exness BTCUSDz, {fecha(REC_MT5['desde'])} → {fecha(REC_MT5['hasta'])}): {REC_MT5['emparejadas']} de {REC_MT5['mt5']['n']} operaciones el mismo lunes, "
                f"correlación de {num(REC_MT5['dif_retorno_bruto_pp']['correlacion'],2)} en el retorno; las {len(REC_MT5['solo_mt5']) + len(REC_MT5['solo_motor'])} restantes, lunes con el percentil en el límite del 30 "
                f"o de 2021, con la ventana del CFD aún corta (su historial empieza en enero de 2021).</p>")
    return out

