def prueba(num_, ico, titulo, ok, pregunta, pasos, criterio, cuerpo, significado, analogia=None, id_="", ver=None):
    ver = ver or ("Superada" if ok else ("No superada" if ok is False else "Informativa"))
    cl = {"Superada": "", "No superada": "ko", "Informativa": "na", "Protocolo": "na"}.get(ver, "ex")
    an = f'<div class="analogia"><span class="ic">💡</span><div>{analogia}</div></div>' if analogia else ""
    return f"""<div class="prueba" id="{id_}"><div class="cab"><span class="num">{num_}</span><span class="ico">{ico}</span><h3>{titulo}</h3><span class="ver {cl}">{ver}</span></div>
<div class="pqc"><div><div class="k">La pregunta</div><div class="q">{pregunta}</div></div>
<div><div class="k">Cómo lo hacemos</div><ol>{''.join(f'<li>{p}</li>' for p in pasos)}</ol></div>
<div><div class="k">El criterio (fijado antes)</div><div class="c">{criterio}</div></div></div>
{an}{cuerpo}<div class="signif"><span class="k">Qué significa para ti</span>{significado}</div></div>"""


def r_(x, d=2):
    return "—" if x is None else num(x, d)


def celda_rev(s):
    if not s or not s.get("n"): return "—"
    if s.get("pf") is None: return f"<span style='color:var(--muted)'>{s['n']} lunes: pocos para medir</span>" + (f" · {pct(s['media']/100, 2, True)}" if s.get("media") is not None else "")
    return f"PF {num(s['pf'])} · {pct(s['media']/100, 2, True)} · n {s['n']}"


