    f1 = M["fase1"]; o, oos, t = f1["IS"], f1["OOS"], f1["TODO"]; orb, trb = f1["OOS_robot"], f1["TODO_robot"]; meta = M["meta"]; anos = int(meta["hasta"][:4]) - int(meta["desde"][:4]); rob = int(ROBOT * 100)
